tool_input.command:
$bak = Join-Path $env:TEMP 'zentao-6931\防汛C端.conf.bak'
$conf = 'D:\nginx\conf\sites-enabled\防汛C端.conf'
$content = (Get-Content -LiteralPath $bak -Raw).TrimStart([char]0xFEFF)
[System.IO.File]::WriteAllText($conf, $content, (New-Object System.Text.UTF8Encoding($false)))
Write-Output ("CONF_BYTES=" + (Get-Item $conf).Length)
if ($content -match 'api/v2\.0/evaluation') { Write-Output "WARN: temp location STILL present" } else { Write-Output "OK: temp location removed" }
Push-Location 'D:\nginx'
try {
  Write-Output "=== nginx -t ==="
  & .\nginx.exe -t *>&1 | ForEach-Object { Write-Output ("  " + $_) }
  Write-Output "=== nginx -s reload ==="
  & .\nginx.exe -s reload *>&1 | ForEach-Object { Write-Output ("  " + $_) }
} finally { Pop-Location }

$tmpDir = Join-Path $env:TEMP 'zentao-6931'
$bakObj = Get-ChildItem -LiteralPath $tmpDir -Filter '*.bak' | Select-Object -First 1
$sitesDir = 'D:\nginx\conf\sites-enabled'
$confObj = Get-ChildItem -LiteralPath $sitesDir -Filter '*.conf' | Where-Object { $_.Name -match '防汛' } | Select-Object -First 1
$raw = [System.IO.File]::ReadAllText($bakObj.FullName)
if ([string]::IsNullOrWhiteSpace($raw)) { Write-Output "ABORT: bak empty"; exit 1 }
if ($raw -match 'api/v2\.0/evaluation') { Write-Output "ABORT: bak has temp location"; exit 1 }
$utf8 = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($confObj.FullName, $raw, $utf8)
$confLen = (Get-Item -LiteralPath $confObj.FullName).Length
Write-Output ("CONF_WRITTEN_LEN=" + $confLen)
$bytes = [System.IO.File]::ReadAllBytes($confObj.FullName)
Write-Output ("HAS_BOM=" + ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF))
Write-Output ("HAS_TEMP_LOC=" + ([System.IO.File]::ReadAllText($confObj.FullName) -match 'api/v2\.0/evaluation'))
Push-Location 'D:\nginx'
try {
  Write-Output "=== nginx -t ==="
  & .\nginx.exe -t *>&1 | ForEach-Object { Write-Output ("  " + $_) }
  Write-Output "=== nginx -s reload ==="
  & .\nginx.exe -s reload *>&1 | ForEach-Object { Write-Output ("  " + $_) }
  Write-Output ("RELOAD_EXIT=" + $LASTEXITCODE)
} finally { Pop-Location }
